### 4. Teste de Regressão Executável

O teste abaixo utiliza o test runner nativo do Node.js (`node:test`) e asserções padrão (`node:assert`). Ele valida que, ao estourar o limite de tempo (5s), o evento de `abort` é emitido no `AbortSignal` repassado ao `fetch`.

```typescript
import { test } from 'node:test';
import assert from 'node:assert';
import { processJob } from './processJob.js';

// Stub sintético da função timeout fornecida no módulo
const timeout = (ms: number) => new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), ms));

test('deve cancelar a requisição HTTP via AbortSignal quando o timeout de 5s for atingido', async () => {
  let signalPassed: AbortSignal | undefined;
  let isAborted = false;

  const mockDeps = {
    client: {
      fetch: (id: string, options?: { signal?: AbortSignal }) => {
        signalPassed = options?.signal;
        return new Promise((resolve, reject) => {
          if (options?.signal) {
            options.signal.addEventListener('abort', () => {
              isAborted = true;
              reject(new DOMException('Request aborted', 'AbortError'));
            });
          }
          // Simula requisição lenta (> 5000ms)
          setTimeout(() => resolve('resposta_tardia'), 6000);
        });
      }
    },
    queue: {
      ack: async (_id: string) => {}
    }
  };

  // Executa e espera a rejeição por timeout
  await assert.rejects(
    async () => {
      await processJob('job-test-123', mockDeps);
    },
    (err: Error) => err.message === 'Timeout' || err.name === 'AbortError'
  );

  // Valida se o sinal de abort foi efetivamente acionado
  assert.strictEqual(signalPassed !== undefined, true, 'O AbortSignal deve ser repassado ao deps.client.fetch');
  assert.strictEqual(signalPassed?.aborted, true, 'O AbortSignal deve estar no estado aborted');
  assert.strictEqual(isAborted, true, 'O listener de abort da requisição HTTP deve ter sido executado');
});
```

